    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 계산기\n  Width: 248\n  Height: 328\n  KeyPreview: true\ncontrols:\n  - name: lblDisplay\n    type: Label\n    properties:\n      Caption: \"0\"\n      Left: 16\n      Top: 16\n      Width: 216\n      Height: 32\n  - name: lblOperator\n    type: Label\n    properties:\n      Left: 16\n      Top: 52\n      Width: 216\n      Height: 20\n  - name: btn7\n    type: Button\n    properties:\n      Caption: \"7\"\n      Left: 16\n      Top: 80\n      Width: 48\n      Height: 40\n  - name: btn8\n    type: Button\n    properties:\n      Caption: \"8\"\n      Left: 72\n      Top: 80\n      Width: 48\n      Height: 40\n  - name: btn9\n    type: Button\n    properties:\n      Caption: \"9\"\n      Left: 128\n      Top: 80\n      Width: 48\n      Height: 40\n  - name: btnDiv\n    type: Button\n    properties:\n      Caption: ÷\n      Left: 184\n      Top: 80\n      Width: 48\n      Height: 40\n  - name: btn4\n    type: Button\n    properties:\n      Caption: \"4\"\n      Left: 16\n      Top: 128\n      Width: 48\n      Height: 40\n  - name: btn5\n    type: Button\n    properties:\n      Caption: \"5\"\n      Left: 72\n      Top: 128\n      Width: 48\n      Height: 40\n  - name: btn6\n    type: Button\n    properties:\n      Caption: \"6\"\n      Left: 128\n      Top: 128\n      Width: 48\n      Height: 40\n  - name: btnMul\n    type: Button\n    properties:\n      Caption: ×\n      Left: 184\n      Top: 128\n      Width: 48\n      Height: 40\n  - name: btn1\n    type: Button\n    properties:\n      Caption: \"1\"\n      Left: 16\n      Top: 176\n      Width: 48\n      Height: 40\n  - name: btn2\n    type: Button\n    properties:\n      Caption: \"2\"\n      Left: 72\n      Top: 176\n      Width: 48\n      Height: 40\n  - name: btn3\n    type: Button\n    properties:\n      Caption: \"3\"\n      Left: 128\n      Top: 176\n      Width: 48\n      Height: 40\n  - name: btnSub\n    type: Button\n    properties:\n      Caption: \"-\"\n      Left: 184\n      Top: 176\n      Width: 48\n      Height: 40\n  - name: btn0\n    type: Button\n    properties:\n      Caption: \"0\"\n      Left: 16\n      Top: 224\n      Width: 48\n      Height: 40\n  - name: btnDot\n    type: Button\n    properties:\n      Caption: .\n      Left: 72\n      Top: 224\n      Width: 48\n      Height: 40\n  - name: btnEquals\n    type: Button\n    properties:\n      Caption: =\n      Left: 128\n      Top: 224\n      Width: 48\n      Height: 40\n  - name: btnAdd\n    type: Button\n    properties:\n      Caption: +\n      Left: 184\n      Top: 224\n      Width: 48\n      Height: 40\n  - name: btnClear\n    type: Button\n    properties:\n      Caption: C\n      Left: 16\n      Top: 272\n      Width: 104\n      Height: 40\n  - name: btnBack\n    type: Button\n    properties:\n      Caption: ←\n      Left: 128\n      Top: 272\n      Width: 104\n      Height: 40\n",
    "Form1.gbas": "' 계산기: 숫자 버튼 10개를 처리기 하나로 처리합니다. Handles 뒤에 버튼을\n' 모두 적고, 어느 버튼이 눌렸는지는 sender로 압니다(DESIGN.md D98).\n' Visual Basic 6에서 컨트롤 배열로 하던 일입니다. 연산 버튼 넷도 처리기\n' 하나입니다. 키보드의 숫자 키, Esc(지우기), Backspace도 됩니다: 폼의\n' KeyPreview가 True여서 폼이 키를 먼저 받습니다(D101).\nDim shown As String      ' 화면에 보이는 수\nDim stored As Double     ' 앞서 넣은 수\nDim pending As String    ' 기다리는 연산: \"+\", \"-\", \"×\", \"÷\", 없으면 \"\"\nDim startNew As Boolean  ' 다음 숫자가 새 수를 시작하는지\n\nSub Form_Load()\n    ClearAll()\nEnd Sub\n\nSub Digit_Click(sender As Button) Handles btn0.Click, btn1.Click, btn2.Click, _\n        btn3.Click, btn4.Click, btn5.Click, btn6.Click, btn7.Click, btn8.Click, btn9.Click\n    TypeDigit(sender.Caption)\nEnd Sub\n\nSub Operator_Click(sender As Button) Handles btnAdd.Click, btnSub.Click, btnMul.Click, btnDiv.Click\n    If Calculate() Then\n        pending = sender.Caption\n        lblOperator.Caption = CStr(stored) & \" \" & pending\n    End If\nEnd Sub\n\nSub btnEquals_Click()\n    If Calculate() Then\n        pending = \"\"\n        lblOperator.Caption = \"\"\n    End If\nEnd Sub\n\nSub btnDot_Click()\n    If startNew Then\n        shown = \"0\"\n        startNew = False\n    End If\n    If InStr(shown, \".\") = 0 Then shown = shown & \".\"\n    lblDisplay.Caption = shown\nEnd Sub\n\nSub btnClear_Click()\n    ClearAll()\nEnd Sub\n\nSub btnBack_Click()\n    If startNew Then Exit Sub\n    If Len(shown) > 1 Then\n        shown = Left(shown, Len(shown) - 1)\n    Else\n        shown = \"0\"\n    End If\n    lblDisplay.Caption = shown\nEnd Sub\n\nSub Form_KeyDown(e As KeyEventArgs)\n    If e.KeyCode >= Keys.D0 And e.KeyCode <= Keys.D9 Then\n        TypeDigit(CStr(e.KeyCode - Keys.D0))\n    ElseIf e.KeyCode >= Keys.NumPad0 And e.KeyCode <= Keys.NumPad9 Then\n        TypeDigit(CStr(e.KeyCode - Keys.NumPad0))\n    ElseIf e.KeyCode = Keys.Escape Then\n        ClearAll()\n    ElseIf e.KeyCode = Keys.Back Then\n        btnBack_Click()\n    End If\nEnd Sub\n\n' 숫자 하나를 화면의 수 뒤에 붙입니다. 연산 뒤에는 새 수를 시작합니다.\nSub TypeDigit(digit As String)\n    If startNew Or shown = \"0\" Then\n        shown = digit\n        startNew = False\n    ElseIf Len(shown) < 12 Then\n        shown = shown & digit\n    End If\n    lblDisplay.Caption = shown\nEnd Sub\n\n' 기다리던 연산을 해서 결과를 보여 주고, 그 결과에서 다음 수를 받습니다.\n' 0으로 나누려 하면 알리고 False를 줍니다.\nFunction Calculate() As Boolean\n    If startNew And pending <> \"\" Then\n        ' 연산 버튼을 잇달아 누르면 마지막 것만 씁니다.\n        Return True\n    End If\n    Dim value As Double = Val(shown)\n    Select Case pending\n        Case \"+\"\n            stored = stored + value\n        Case \"-\"\n            stored = stored - value\n        Case \"×\"\n            stored = stored * value\n        Case \"÷\"\n            If value = 0 Then\n                MsgBox(\"0으로 나눌 수 없습니다.\")\n                Return False\n            End If\n            stored = stored / value\n        Case Else\n            stored = value\n    End Select\n    ' 0.1 + 0.2처럼 소수가 2진수로 딱 떨어지지 않아 생기는 끝자리를 버립니다.\n    stored = Round(stored, 10)\n    shown = CStr(stored)\n    lblDisplay.Caption = shown\n    startNew = True\n    Return True\nEnd Function\n\nSub ClearAll()\n    shown = \"0\"\n    stored = 0\n    pending = \"\"\n    startNew = False\n    lblDisplay.Caption = shown\n    lblOperator.Caption = \"\"\nEnd Sub\n",
  },
