    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: Duel\n  Width: 640\n  Height: 400\n  BackColor: \"#1B1F2A\"\ncontrols:\n  - name: lblFloor\n    type: Label\n    properties: { Caption: \"  1P  A D 걷기 · W 점프 · S 앉기 · F 주먹 · G 발차기      2P  ← → · ↑ · ↓ · . · /  (같은 순서)      B 훈련 보기\", Left: 0, Top: 360, Width: 640, Height: 40, FontSize: 10.0, ForeColor: \"#C8CCD6\", BackColor: \"#3A3F4B\", Anchor: Left Right Bottom }\n  - name: lblName1\n    type: Label\n    properties: { Caption: 1P, Left: 12, Top: 10, Width: 40, Height: 20, FontBold: true, ForeColor: \"#BFD6FF\" }\n  - name: lblBar1\n    type: Label\n    properties: { Caption: \"\", Left: 52, Top: 12, Width: 220, Height: 16, BackColor: \"#3D7BE0\" }\n  - name: lblWins1\n    type: Label\n    properties: { Caption: \"\", Left: 52, Top: 32, Width: 160, Height: 18, ForeColor: Gold }\n  - name: lblClock\n    type: Label\n    properties: { Caption: \"60\", Left: 290, Top: 4, Width: 60, Height: 32, FontSize: 20.0, FontBold: true, ForeColor: White }\n  - name: lblName2\n    type: Label\n    properties: { Caption: 2P, Left: 596, Top: 10, Width: 40, Height: 20, FontBold: true, ForeColor: \"#FFC7D1\", Anchor: Right Top }\n  - name: lblBar2\n    type: Label\n    properties: { Caption: \"\", Left: 368, Top: 12, Width: 220, Height: 16, BackColor: \"#D9465F\", Anchor: Right Top }\n  - name: lblWins2\n    type: Label\n    properties: { Caption: \"\", Left: 428, Top: 32, Width: 160, Height: 18, ForeColor: Gold, Anchor: Right Top }\n  - name: lblInputs1\n    type: Label\n    properties: { Caption: \"\", Left: 12, Top: 56, Width: 300, Height: 20, FontSize: 10.0, ForeColor: \"#BFD6FF\", Visible: false }\n  - name: lblInputs2\n    type: Label\n    properties: { Caption: \"\", Left: 328, Top: 56, Width: 300, Height: 20, FontSize: 10.0, ForeColor: \"#FFC7D1\", Visible: false, Anchor: Right Top }\n  - name: lblMessage\n    type: Label\n    properties: { Caption: \"\", Left: 120, Top: 130, Width: 400, Height: 40, FontSize: 22.0, FontBold: true, ForeColor: Gold }\n  - name: btnOne\n    type: Button\n    properties: { Caption: 1인 (컴퓨터와), Left: 170, Top: 190, Width: 140, Height: 36 }\n  - name: btnTwo\n    type: Button\n    properties: { Caption: 2인, Left: 330, Top: 190, Width: 140, Height: 36 }\n  - name: sprFighter1\n    type: Sprite\n    properties: { Frames: p1_stand.png, Left: 120, Top: 248, Width: 96, Height: 112 }\n  - name: sprFighter2\n    type: Sprite\n    properties: { Frames: p2_stand.png, FlipX: true, Left: 424, Top: 248, Width: 96, Height: 112 }\n  - name: sprHurt1\n    type: Sprite\n    properties: { Left: 148, Top: 256, Width: 40, Height: 104 }\n  - name: sprHurt2\n    type: Sprite\n    properties: { Left: 452, Top: 256, Width: 40, Height: 104 }\n  - name: sprHit1\n    type: Sprite\n    properties: { Left: 0, Top: 0, Width: 1, Height: 1, Visible: false }\n  - name: sprHit2\n    type: Sprite\n    properties: { Left: 0, Top: 0, Width: 1, Height: 1, Visible: false }\n  - name: tmrGame\n    type: Timer\n    properties: { Interval: 16 }\n",
    "Form1.gbas": "' 격투 게임의 정석(docs/DESIGN.md D139): Timer 하나가 게임 루프이고, 선수마다\n' 상태 기계가 있습니다. 선수는 키를 직접 읽지 않고 \"입력 묶음\"만 읽으므로,\n' 사람(키)과 컴퓨터(규칙)가 같은 규칙으로 싸웁니다. 공격은 표(프레임 데이터)로\n' 정하고, 맞는 곳(허트박스)과 때리는 곳(히트박스)은 그림 없는 Sprite입니다.\n' B를 누르면 훈련 보기: 상자를 색으로, 입력 묶음을 글자로 보입니다.\n\n' 선수 하나가 이번 틱에 하려는 것. 키나 컴퓨터가 채웁니다.\nStructure Inputs\n    Forward As Boolean      ' 상대 쪽으로\n    Back As Boolean         ' 상대 반대쪽으로\n    Jump As Boolean\n    Crouch As Boolean\n    Punch As Boolean\n    Kick As Boolean\n    Block As Boolean        ' 뒤로 누르고 있음\nEnd Structure\n\n' 공격 하나의 프레임 데이터. 시간은 ms, 자리는 픽셀입니다.\nStructure Attack\n    Look As String          ' 그림: punch, kick, lowpunch, lowkick\n    Startup As Integer      ' 누른 뒤 맞히기 시작할 때까지\n    Active As Integer       ' 맞힐 수 있는 동안\n    Recovery As Integer     ' 거두는 동안\n    Damage As Integer\n    Reach As Integer        ' 히트박스가 몸 앞으로 뻗는 길이\n    Top As Integer          ' 히트박스 위쪽, 선수 그림 위에서부터\n    Height As Integer\n    Low As Boolean          ' 서서 막으면 못 막고, 앉아서 막아야 함\nEnd Structure\n\n' 선수의 상태\nConst Idle As Integer = 0\nConst Walking As Integer = 1\nConst Crouching As Integer = 2\nConst Jumping As Integer = 3\nConst Attacking As Integer = 4\nConst Blocking As Integer = 5\nConst Hurt As Integer = 6\nConst Down As Integer = 7\n\nConst FloorTop As Double = 248      ' 바닥에 선 선수 그림의 Y\nConst WalkSpeed As Double = 170     ' 초당 픽셀\nConst JumpSpeed As Double = -560\nConst Gravity As Double = 1500      ' 초당 초당 픽셀\nConst HitStop As Integer = 80       ' 맞은 순간 모두 멈추는 ms\nConst HurtTime As Integer = 300\nConst RoundTime As Integer = 60000\nConst MaxHealth As Integer = 100\nConst BarWidth As Integer = 220\n\nDim fighters(1) As Sprite\nDim hurtboxes(1) As Sprite\nDim hitboxes(1) As Sprite\nDim prefix(1) As String\nDim state(1) As Integer\nDim stateAt(1) As Integer           ' 지금 상태가 된 때(ms)\nDim attackOf(1) As Integer          ' 하는 중인 공격, attacks의 번호\nDim landed(1) As Boolean            ' 이번 공격이 이미 맞혔음\nDim health(1) As Integer\nDim facing(1) As Integer            ' 1: 오른쪽을 봄, -1: 왼쪽을 봄\nDim wins(1) As Integer\nDim inputs(1) As Inputs\nDim attacks(3) As Attack\n\nDim computer As Boolean             ' 2P를 컴퓨터가 함\nDim training As Boolean\nDim fighting As Boolean             ' 라운드가 진행 중\nDim roundNumber As Integer\nDim roundStart As Integer\nDim nextRoundAt As Integer          ' 0이 아니면 그때 다음 라운드\nDim messageUntil As Integer\nDim stopUntil As Integer            ' 히트 스톱이 끝나는 때\nDim lastTime As Integer\nDim cpuNextAttack As Integer\nDim cpuSeen As Integer              ' 컴퓨터가 본 상대 공격의 시작 시각\nDim cpuBlocks As Boolean\nDim cpuCount As Integer\n\nSub Form_Load()\n    fighters(0) = sprFighter1\n    fighters(1) = sprFighter2\n    hurtboxes(0) = sprHurt1\n    hurtboxes(1) = sprHurt2\n    hitboxes(0) = sprHit1\n    hitboxes(1) = sprHit2\n    prefix(0) = \"p1_\"\n    prefix(1) = \"p2_\"\n    ' 프레임 데이터: 주먹은 빠르고 약하고, 발차기는 느리고 셉니다. 앉아서 하면 낮은 공격.\n    attacks(0) = New Attack With {.Look = \"punch\", .Startup = 60, .Active = 80, .Recovery = 160,\n                                  .Damage = 8, .Reach = 30, .Top = 26, .Height = 22, .Low = False}\n    attacks(1) = New Attack With {.Look = \"kick\", .Startup = 120, .Active = 100, .Recovery = 240,\n                                  .Damage = 12, .Reach = 34, .Top = 50, .Height = 26, .Low = False}\n    attacks(2) = New Attack With {.Look = \"lowpunch\", .Startup = 70, .Active = 80, .Recovery = 180,\n                                  .Damage = 6, .Reach = 30, .Top = 60, .Height = 22, .Low = True}\n    attacks(3) = New Attack With {.Look = \"lowkick\", .Startup = 130, .Active = 100, .Recovery = 260,\n                                  .Damage = 10, .Reach = 36, .Top = 92, .Height = 18, .Low = True}\n    facing(0) = 1\n    facing(1) = -1\n    lblMessage.Caption = \"1인 또는 2인을 고르세요\"\n    ShowTraining()\nEnd Sub\n\nSub btnOne_Click()\n    computer = True\n    StartMatch()\nEnd Sub\n\nSub btnTwo_Click()\n    computer = False\n    StartMatch()\nEnd Sub\n\n' 경기 시작. 버튼은 숨겨서, 경기 중에 스페이스나 Enter를 가져가지 않게 합니다.\nSub StartMatch()\n    btnOne.Visible = False\n    btnTwo.Visible = False\n    wins(0) = 0\n    wins(1) = 0\n    roundNumber = 0\n    Keyboard.ClearPressed()\n    StartRound()\n    lastTime = Milliseconds()\n    tmrGame.Start()\nEnd Sub\n\nSub StartRound()\n    Dim now As Integer = Milliseconds()\n    Dim f As Integer\n    For f = 0 To 1\n        health(f) = MaxHealth\n        landed(f) = False\n        SetState(f, Idle, now)\n        fighters(f).Y = FloorTop\n        fighters(f).SpeedX = 0\n        fighters(f).SpeedY = 0\n        hitboxes(f).Visible = False\n    Next\n    fighters(0).X = 120\n    fighters(1).X = 424\n    facing(0) = 1\n    facing(1) = -1\n    roundNumber = roundNumber + 1\n    roundStart = now\n    nextRoundAt = 0\n    stopUntil = 0\n    cpuNextAttack = now + 800\n    fighting = True\n    Say(\"라운드 \" & roundNumber, now + 1000)\n    For f = 0 To 1\n        SetLook(f)\n    Next\n    ShowBars()\nEnd Sub\n\n' 게임 루프: 입력 묶음을 채우고, 선수를 움직이고, 상자를 놓고, 맞음을 봅니다.\nSub tmrGame_Tick()\n    Dim now As Integer = Milliseconds()\n    Dim dt As Integer = now - lastTime\n    If dt > 50 Then dt = 50\n    lastTime = now\n    If Keyboard.WasPressed(Keys.B) Then\n        training = Not training\n        ShowTraining()\n    End If\n    If now < stopUntil Then Exit Sub        ' 히트 스톱: 아무것도 움직이지 않음\n    If messageUntil > 0 And now >= messageUntil Then Say(\"\", 0)\n\n    ' 1. 입력 묶음: 라운드 중에만 채웁니다.\n    Dim f As Integer\n    For f = 0 To 1\n        Dim want As Inputs = KeysOf(f)\n        If f = 1 And computer Then want = ComputerOf(1, now)\n        If Not fighting Then want = New Inputs With {.Forward = False}\n        inputs(f) = want\n    Next\n\n    ' 2. 상태 기계와 움직임, 3. 서로 마주 봄과 밀어냄, 4. 상자\n    For f = 0 To 1\n        StepFighter(f, now, dt)\n    Next\n    FaceEachOther()\n    KeepApart()\n    For f = 0 To 1\n        PlaceBoxes(f, now)\n        SetLook(f)\n    Next\n\n    ' 5. 맞음: 두 선수가 같은 틱에 서로 맞힐 수도 있습니다.\n    Dim hit0 As Boolean = Touches(0, 1)\n    Dim hit1 As Boolean = Touches(1, 0)\n    If hit0 Then Strike(0, 1, now)\n    If hit1 Then Strike(1, 0, now)\n\n    ' 6. 시계와 라운드\n    If fighting Then\n        Dim secs As Integer = (RoundTime - (now - roundStart) + 999) \\ 1000\n        If secs < 0 Then secs = 0\n        If lblClock.Caption <> CStr(secs) Then lblClock.Caption = CStr(secs)\n        If now - roundStart >= RoundTime Then TimeUp(now)\n    ElseIf nextRoundAt > 0 And now >= nextRoundAt Then\n        NextRound()\n    End If\n    If training Then ShowInputs()\nEnd Sub\n\n' 사람의 키로 채운 입력 묶음. 앞·뒤는 바라보는 방향으로 셉니다.\nFunction KeysOf(f As Integer) As Inputs\n    Dim leftKey As Integer = Keys.A\n    Dim rightKey As Integer = Keys.D\n    Dim upKey As Integer = Keys.W\n    Dim downKey As Integer = Keys.S\n    Dim punchKey As Integer = Keys.F\n    Dim kickKey As Integer = Keys.G\n    If f = 1 Then\n        leftKey = Keys.Left\n        rightKey = Keys.Right\n        upKey = Keys.Up\n        downKey = Keys.Down\n        punchKey = Keys.OemPeriod\n        kickKey = Keys.OemQuestion\n    End If\n    Dim toward As Integer = rightKey\n    Dim away As Integer = leftKey\n    If facing(f) < 0 Then\n        toward = leftKey\n        away = rightKey\n    End If\n    Dim back As Boolean = Keyboard.IsDown(away)\n    Return New Inputs With {.Forward = Keyboard.IsDown(toward), .Back = back,\n                            .Jump = Keyboard.WasPressed(upKey), .Crouch = Keyboard.IsDown(downKey),\n                            .Punch = Keyboard.WasPressed(punchKey), .Kick = Keyboard.WasPressed(kickKey),\n                            .Block = back}\nEnd Function\n\n' 컴퓨터가 채운 입력 묶음: 다가가고, 닿으면 공격하고, 상대 공격은 세 번에 두 번 막습니다.\nFunction ComputerOf(f As Integer, now As Integer) As Inputs\n    Dim other As Integer = 1 - f\n    Dim gap As Double = Abs(Centre(other) - Centre(f))\n    If state(other) = Attacking And gap < 110 Then\n        If stateAt(other) <> cpuSeen Then\n            cpuSeen = stateAt(other)\n            cpuCount = cpuCount + 1\n            cpuBlocks = cpuCount Mod 3 <> 0\n        End If\n        If cpuBlocks Then\n            Return New Inputs With {.Back = True, .Block = True, .Crouch = attacks(attackOf(other)).Low}\n        End If\n    End If\n    If gap > 70 Then Return New Inputs With {.Forward = True}\n    If now >= cpuNextAttack And state(f) <> Attacking Then\n        cpuNextAttack = now + 700\n        cpuCount = cpuCount + 1\n        If cpuCount Mod 2 = 0 Then Return New Inputs With {.Kick = True}\n        Return New Inputs With {.Punch = True}\n    End If\n    Return New Inputs With {.Forward = False}\nEnd Function\n\n' 선수 하나의 상태 기계: 입력 묶음만 보고 다음 상태와 속도를 정합니다.\nSub StepFighter(f As Integer, now As Integer, dt As Integer)\n    Dim spr As Sprite = fighters(f)\n    Dim want As Inputs = inputs(f)\n    Dim since As Integer = now - stateAt(f)\n    Select Case state(f)\n        Case Idle, Walking, Crouching, Blocking\n            If want.Jump Then\n                SetState(f, Jumping, now)\n                spr.SpeedY = JumpSpeed\n                Go(f, 0)\n                If want.Forward Then Go(f, facing(f) * WalkSpeed)\n                If want.Back Then Go(f, -facing(f) * WalkSpeed)\n            ElseIf want.Punch Or want.Kick Then\n                Dim a As Integer = 0\n                If want.Kick Then a = 1\n                If want.Crouch Then a = a + 2\n                attackOf(f) = a\n                landed(f) = False\n                SetState(f, Attacking, now)\n                Go(f, 0)\n            ElseIf want.Block And state(1 - f) = Attacking Then\n                Become(f, Blocking, now)\n                Go(f, 0)\n            ElseIf want.Crouch Then\n                Become(f, Crouching, now)\n                Go(f, 0)\n            ElseIf want.Forward Then\n                Become(f, Walking, now)\n                Go(f, facing(f) * WalkSpeed)\n            ElseIf want.Back Then\n                Become(f, Walking, now)\n                Go(f, -facing(f) * WalkSpeed * 0.8)\n            Else\n                Become(f, Idle, now)\n                Go(f, 0)\n            End If\n        Case Attacking\n            Dim atk As Attack = attacks(attackOf(f))\n            If since >= atk.Startup + atk.Active + atk.Recovery Then\n                If atk.Low Then\n                    SetState(f, Crouching, now)\n                Else\n                    SetState(f, Idle, now)\n                End If\n            End If\n        Case Hurt\n            Go(f, 0)\n            If since >= HurtTime Then SetState(f, Idle, now)\n        Case Down\n            Go(f, 0)\n    End Select\n    ' 공중에 있으면 떨어지고, 바닥에 닿으면 섭니다.\n    Dim flying As Boolean = spr.Y < FloorTop Or spr.SpeedY <> 0\n    If flying Then spr.SpeedY = spr.SpeedY + Gravity * dt / 1000\n    spr.Move(dt)\n    If flying And spr.Y >= FloorTop Then\n        spr.Y = FloorTop\n        spr.SpeedY = 0\n        If state(f) = Jumping Then SetState(f, Idle, now)\n    End If\n    Fence(f)\nEnd Sub\n\n' 걷는 속도. 바뀔 때만 정합니다.\nSub Go(f As Integer, speed As Double)\n    If fighters(f).SpeedX <> speed Then fighters(f).SpeedX = speed\nEnd Sub\n\n' 땅에 서서 다른 일을 하지 않을 때 서로 마주 봅니다.\nSub FaceEachOther()\n    Dim f As Integer\n    For f = 0 To 1\n        If state(f) <= Crouching Or state(f) = Blocking Then\n            If Centre(1 - f) > Centre(f) Then facing(f) = 1\n            If Centre(1 - f) < Centre(f) Then facing(f) = -1\n        End If\n    Next\nEnd Sub\n\n' 몸이 겹치지 않게 둘을 반씩 밀어냅니다.\nSub KeepApart()\n    Const Closest As Double = 50\n    Dim gap As Double = Centre(1) - Centre(0)\n    If Abs(gap) >= Closest Then Exit Sub\n    Dim push As Double = (Closest - Abs(gap)) / 2\n    If gap >= 0 Then\n        fighters(0).X = fighters(0).X - push\n        fighters(1).X = fighters(1).X + push\n    Else\n        fighters(0).X = fighters(0).X + push\n        fighters(1).X = fighters(1).X - push\n    End If\n    Fence(0)\n    Fence(1)\nEnd Sub\n\n' 선수 그림 전체가 경기장 안에 남게 합니다. 쓰러진 그림은 프레임을 거의 다 차지하므로,\n' 밀려나도 끝에서 잘리지 않게 그림의 양쪽 끝을 경계로 씁니다(왼쪽과 오른쪽 모두).\nSub Fence(f As Integer)\n    If fighters(f).X < 0 Then fighters(f).X = 0\n    If fighters(f).X > Me.Width - fighters(f).Width Then fighters(f).X = Me.Width - fighters(f).Width\nEnd Sub\n\n' 허트박스는 몸에, 히트박스는 공격이 맞힐 수 있는 동안만 바라보는 쪽 앞에 놓습니다.\nSub PlaceBoxes(f As Integer, now As Integer)\n    Dim spr As Sprite = fighters(f)\n    Dim c As Double = Centre(f)\n    Dim low As Boolean = state(f) = Crouching\n    If state(f) = Attacking Then low = attacks(attackOf(f)).Low\n    Dim body As Sprite = hurtboxes(f)\n    Dim seen As Boolean = state(f) <> Down\n    If body.Visible <> seen Then body.Visible = seen\n    Dim top As Integer = 6\n    Dim tall As Integer = 106\n    If low Then\n        top = 44\n        tall = 68\n    End If\n    If body.Height <> tall Then body.Height = tall\n    body.Y = spr.Y + top\n    body.X = c - 20\n\n    Dim hit As Sprite = hitboxes(f)\n    If hit.Visible Then hit.Visible = False\n    If state(f) <> Attacking Or landed(f) Then Exit Sub\n    Dim atk As Attack = attacks(attackOf(f))\n    Dim since As Integer = now - stateAt(f)\n    If since < atk.Startup Or since >= atk.Startup + atk.Active Then Exit Sub\n    hit.Width = atk.Reach\n    hit.Height = atk.Height\n    hit.Y = spr.Y + atk.Top\n    If facing(f) > 0 Then\n        hit.X = c + 16\n    Else\n        hit.X = c - 16 - atk.Reach\n    End If\n    hit.Visible = True\nEnd Sub\n\n' a의 히트박스가 d의 허트박스에 닿는지\nFunction Touches(a As Integer, d As Integer) As Boolean\n    If Not hitboxes(a).Visible Or Not fighting Then Return False\n    Return hitboxes(a).Hits(hurtboxes(d))\nEnd Function\n\n' a가 d를 맞힘: 막았으면 덜 밀리고 체력은 그대로, 아니면 체력이 줄고 휘청입니다.\nSub Strike(a As Integer, d As Integer, now As Integer)\n    Dim atk As Attack = attacks(attackOf(a))\n    landed(a) = True\n    hitboxes(a).Visible = False\n    Dim ready As Boolean = state(d) <= Crouching Or state(d) = Blocking\n    Dim blocked As Boolean = ready And inputs(d).Block And (Not atk.Low Or inputs(d).Crouch)\n    If blocked Then\n        SetState(d, Blocking, now)\n        fighters(d).X = fighters(d).X + facing(a) * 12\n        Sound.Play(\"block.wav\")\n    Else\n        health(d) = health(d) - atk.Damage\n        If health(d) < 0 Then health(d) = 0\n        fighters(d).X = fighters(d).X + facing(a) * 28\n        Sound.Play(\"hit.wav\")\n        If health(d) = 0 Then\n            KnockOut(d, now)\n        Else\n            SetState(d, Hurt, now)\n        End If\n    End If\n    Fence(d)\n    stopUntil = now + HitStop\n    ShowBars()\nEnd Sub\n\nSub KnockOut(d As Integer, now As Integer)\n    SetState(d, Down, now)\n    SetLook(d)\n    Sound.Play(\"ko.wav\")\n    EndRound(1 - d, \"KO\", now)\nEnd Sub\n\nSub TimeUp(now As Integer)\n    If health(0) > health(1) Then\n        EndRound(0, \"시간 끝\", now)\n    ElseIf health(1) > health(0) Then\n        EndRound(1, \"시간 끝\", now)\n    Else\n        EndRound(-1, \"시간 끝\", now)\n    End If\nEnd Sub\n\n' 라운드 끝: 이긴 쪽(없으면 -1)에 1승. 2초 뒤 다음 라운드나 경기 끝.\nSub EndRound(winner As Integer, why As String, now As Integer)\n    fighting = False\n    hitboxes(0).Visible = False\n    hitboxes(1).Visible = False\n    If winner >= 0 Then\n        wins(winner) = wins(winner) + 1\n        Say(why & \"! \" & (winner + 1) & \"P가 이겼습니다\", 0)\n    Else\n        Say(why & \"! 비겼습니다\", 0)\n    End If\n    nextRoundAt = now + 2000\n    ShowBars()\nEnd Sub\n\nSub NextRound()\n    nextRoundAt = 0\n    If wins(0) >= 2 Or wins(1) >= 2 Then\n        tmrGame.Stop()\n        If wins(0) >= 2 Then\n            Say(\"1P 승리!\", 0)\n        Else\n            Say(\"2P 승리!\", 0)\n        End If\n        ' 경기가 끝났으니 버튼을 다시 보입니다.\n        btnOne.Caption = \"다시: 1인\"\n        btnTwo.Caption = \"다시: 2인\"\n        btnOne.Visible = True\n        btnTwo.Visible = True\n    Else\n        StartRound()\n    End If\nEnd Sub\n\n' 새 상태로 바꾸고 그때를 적습니다.\nSub SetState(f As Integer, s As Integer, now As Integer)\n    state(f) = s\n    stateAt(f) = now\nEnd Sub\n\n' 이미 그 상태면 그대로(걷는 그림이 처음부터 다시 시작하지 않게).\nSub Become(f As Integer, s As Integer, now As Integer)\n    If state(f) <> s Then SetState(f, s, now)\nEnd Sub\n\n' 상태에 맞는 그림. 그림은 오른쪽을 보고 있고, 왼쪽을 보면 FlipX로 뒤집습니다.\nSub SetLook(f As Integer)\n    Dim look As String = \"stand\"\n    Select Case state(f)\n        Case Walking\n            look = \"walk\"\n        Case Crouching\n            look = \"crouch\"\n        Case Jumping\n            look = \"jump\"\n        Case Attacking\n            look = attacks(attackOf(f)).Look\n        Case Blocking\n            look = \"block\"\n            If inputs(f).Crouch Then look = \"crouch\"\n        Case Hurt\n            look = \"hurt\"\n        Case Down\n            look = \"down\"\n    End Select\n    Dim frames As String = prefix(f) & look & \".png\"\n    Dim frameTime As Integer = 0\n    If look = \"walk\" Then\n        frames = prefix(f) & \"walk.png, \" & prefix(f) & \"stand.png\"\n        frameTime = 140\n    End If\n    Dim spr As Sprite = fighters(f)\n    If spr.Frames <> frames Then\n        spr.Frame = 0\n        spr.Frames = frames\n        spr.FrameTime = frameTime\n    End If\n    Dim turned As Boolean = facing(f) < 0\n    If spr.FlipX <> turned Then spr.FlipX = turned\nEnd Sub\n\nFunction Centre(f As Integer) As Double\n    Return fighters(f).X + fighters(f).Width / 2\nEnd Function\n\n' 훈련 보기: 상자에 반투명 그림을 주고 입력 묶음을 보입니다. 끄면 그림 없는 상자로.\nSub ShowTraining()\n    Dim f As Integer\n    For f = 0 To 1\n        If training Then\n            hurtboxes(f).Frames = \"hurtbox.png\"\n            hitboxes(f).Frames = \"hitbox.png\"\n        Else\n            hurtboxes(f).Frames = \"\"\n            hitboxes(f).Frames = \"\"\n        End If\n    Next\n    lblInputs1.Visible = training\n    lblInputs2.Visible = training\n    If training Then ShowInputs()\nEnd Sub\n\nSub ShowInputs()\n    lblInputs1.Caption = \"1P \" & Marks(inputs(0))\n    lblInputs2.Caption = \"2P \" & Marks(inputs(1))\nEnd Sub\n\nFunction Marks(want As Inputs) As String\n    Dim s As String = \"\"\n    If want.Forward Then s = s & \"앞 \"\n    If want.Back Then s = s & \"뒤 \"\n    If want.Jump Then s = s & \"점프 \"\n    If want.Crouch Then s = s & \"앉기 \"\n    If want.Punch Then s = s & \"주먹 \"\n    If want.Kick Then s = s & \"발차기 \"\n    If want.Block Then s = s & \"막기\"\n    Return s\nEnd Function\n\nSub ShowBars()\n    lblBar1.Width = health(0) * BarWidth \\ MaxHealth\n    lblBar2.Width = health(1) * BarWidth \\ MaxHealth\n    lblBar2.Left = 588 - lblBar2.Width\n    If lblWins1.Caption <> Stars(wins(0)) Then lblWins1.Caption = Stars(wins(0))\n    If lblWins2.Caption <> Stars(wins(1)) Then lblWins2.Caption = Stars(wins(1))\nEnd Sub\n\nFunction Stars(n As Integer) As String\n    If n = 0 Then Return \"\"\n    If n = 1 Then Return \"★\"\n    Return \"★★\"\nEnd Function\n\n' 가운데 글자를 보이고, clearAt(ms)이 되면 지웁니다. 0이면 그대로 둡니다.\nSub Say(text As String, clearAt As Integer)\n    lblMessage.Caption = text\n    messageUntil = clearAt\nEnd Sub\n",
  },
  "hello": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: Hello\n  Width: 320\n  Height: 120\ncontrols:\n  - name: lblMessage\n    type: Label\n    properties:\n      Left: 16\n      Top: 16\n      Width: 288\n  - name: btnHello\n    type: Button\n    properties:\n      Caption: Say hello\n      Left: 16\n      Top: 56\n      Width: 120\n",
    "Form1.gbas": "Dim clickCount As Integer\n\nSub Form_Load()\n    lblMessage.Caption = \"Press the button\"\nEnd Sub\n\nSub btnHello_Click()\n    clickCount = clickCount + 1\n    Dim name = InputBox(\"What is your name?\")\n    MsgBox(\"Hello, \" & name & \"! (\" & clickCount & \")\")\nEnd Sub\n",
    "Hello.gbproj":
        "formatVersion: 1\nname: Hello\nstartup: Form1\nforms:\n  - Form1\n",
  },
  "livequiz": {
    "FormPhone.form.yaml": "formatVersion: 1\nproperties:\n  Caption: LiveQuiz - 폰\n  Width: 360\n  Height: 480\ncontrols:\n  - name: lblStep\n    type: Label\n    properties:\n      Caption: 방 코드와 별명을 넣고 \"들어가기\"를 누르세요.\n      Left: 16\n      Top: 12\n      Width: 328\n      Height: 40\n  - name: txtCode\n    type: TextBox\n    properties:\n      Left: 16\n      Top: 56\n      Width: 120\n  - name: txtNickname\n    type: TextBox\n    properties:\n      Left: 144\n      Top: 56\n      Width: 200\n  - name: btnJoin\n    type: Button\n    properties:\n      Caption: 들어가기\n      Left: 16\n      Top: 96\n      Width: 328\n  - name: lblQuestion\n    type: Label\n    properties:\n      Left: 16\n      Top: 144\n      Width: 328\n      Height: 40\n  - name: btnChoice0\n    type: Button\n    properties:\n      Left: 16\n      Top: 192\n      Width: 328\n      Height: 40\n      Caption: \"1\"\n      Tag: \"0\"\n  - name: btnChoice1\n    type: Button\n    properties:\n      Left: 16\n      Top: 240\n      Width: 328\n      Height: 40\n      Caption: \"2\"\n      Tag: \"1\"\n  - name: btnChoice2\n    type: Button\n    properties:\n      Left: 16\n      Top: 288\n      Width: 328\n      Height: 40\n      Caption: \"3\"\n      Tag: \"2\"\n  - name: btnChoice3\n    type: Button\n    properties:\n      Left: 16\n      Top: 336\n      Width: 328\n      Height: 40\n      Caption: \"4\"\n      Tag: \"3\"\n  - name: lblResult\n    type: Label\n    properties:\n      Left: 16\n      Top: 392\n      Width: 328\n  - name: lblRank\n    type: Label\n    properties:\n      Left: 16\n      Top: 420\n      Width: 328\n  - name: rmQuiz\n    type: Room\n",
    "FormPhone.gbas": "' 폰 쪽: TV가 보여 주는 방 코드로 들어가, 문제가 오면 보기 버튼으로 답합니다.\n' 답은 TV에게만 보냅니다(SendTo). 다른 폰은 내 답을 보지 못합니다.\n\nDim host As String          ' TV의 멤버 ID: 문제와 함께 옵니다\nDim questionNo As Integer\n\nSub Form_Load()\n    ShowChoices(False)\nEnd Sub\n\n' 방 코드는 대문자로: 폰의 자판이 소문자를 넣어도 맞게.\nSub txtCode_Changed()\n    Dim upper As String = txtCode.Text.ToUpper()\n    If upper <> txtCode.Text Then txtCode.Text = upper\nEnd Sub\n\nSub btnJoin_Click()\n    If txtNickname.Text.Trim() = \"\" Then\n        MsgBox(\"별명을 넣어 주세요.\")\n        Exit Sub\n    End If\n    Try\n        ' 방에 들어갈 때까지 기다립니다. 없는 방이면 오류가 납니다.\n        rmQuiz.Join(txtCode.Text, txtNickname.Text)\n    Catch ex As Exception\n        MsgBox(ex.Message)\n        Exit Sub\n    End Try\n    lblStep.Caption = txtNickname.Text & \" 님, 들어왔습니다. 문제를 기다리세요.\"\n    ' 들어온 뒤에는 코드와 별명을 바꾸지 못하게 합니다.\n    btnJoin.Caption = \"방 \" & rmQuiz.Code\n    btnJoin.Enabled = False\n    txtCode.Enabled = False\n    txtNickname.Enabled = False\nEnd Sub\n\nSub rmQuiz_Message(e As RoomEventArgs)\n    Dim m As Json = e.Json\n    Select Case m(\"kind\").AsString\n        Case \"question\"\n            host = m(\"host\").AsString\n            questionNo = m(\"no\").AsInteger\n            lblQuestion.Caption = questionNo & \". \" & m(\"text\").AsString\n            Dim choices As Json = m(\"choices\")\n            btnChoice0.Caption = \"1) \" & choices(0).AsString\n            btnChoice1.Caption = \"2) \" & choices(1).AsString\n            btnChoice2.Caption = \"3) \" & choices(2).AsString\n            btnChoice3.Caption = \"4) \" & choices(3).AsString\n            ShowChoices(True)\n            lblResult.Caption = m(\"seconds\").AsInteger & \"초 안에 고르세요!\"\n        Case \"result\"\n            If m(\"correct\").AsBoolean Then\n                lblResult.Caption = \"정답! 지금 \" & m(\"score\").AsInteger & \"점\"\n            Else\n                lblResult.Caption = \"아쉽네요. 지금 \" & m(\"score\").AsInteger & \"점\"\n            End If\n        Case \"score\"\n            Dim board As Json = m(\"board\")\n            For i As Integer = 0 To board.Count - 1\n                If board(i)(\"member\").AsString = rmQuiz.Me Then\n                    lblRank.Caption = \"내 순위: \" & (i + 1) & \" / \" & board.Count\n                End If\n            Next\n            ShowChoices(False)\n        Case \"end\"\n            lblStep.Caption = \"끝났습니다. 고맙습니다!\"\n            ShowChoices(False)\n    End Select\nEnd Sub\n\nSub Choice_Click(sender As Button) Handles btnChoice0.Click, btnChoice1.Click, btnChoice2.Click, btnChoice3.Click\n    Dim chosen As String = sender.Caption\n    Dim answer As New Json\n    answer(\"kind\") = \"answer\"\n    answer(\"no\") = questionNo\n    answer(\"choice\") = CInt(sender.Tag)\n    rmQuiz.SendTo(host, answer.Text)\n    ShowChoices(False)\n    lblResult.Caption = \"답을 보냈습니다: \" & chosen\nEnd Sub\n\nSub rmQuiz_Closed(e As RoomEventArgs)\n    ShowChoices(False)\n    lblStep.Caption = \"방이 끝났습니다(\" & e.Reason & \").\"\nEnd Sub\n\n' 고를 수 없을 때는 보기 버튼을 끄고 번호만 남깁니다. 문제가 오면 번호와\n' 보기를 함께 보입니다: TV가 멀거나 작아도 폰에서 읽고 고를 수 있게.\nSub ShowChoices(shown As Boolean)\n    btnChoice0.Enabled = shown\n    btnChoice1.Enabled = shown\n    btnChoice2.Enabled = shown\n    btnChoice3.Enabled = shown\n    If shown Then Exit Sub\n    btnChoice0.Caption = \"1\"\n    btnChoice1.Caption = \"2\"\n    btnChoice2.Caption = \"3\"\n    btnChoice3.Caption = \"4\"\nEnd Sub\n",
    "FormStart.form.yaml": "formatVersion: 1\nproperties:\n  Caption: LiveQuiz\n  Width: 360\n  Height: 220\ncontrols:\n  - name: lblTitle\n    type: Label\n    properties:\n      Caption: 실시간 퀴즈. TV(또는 교실 화면)에서 방을 만들고, 폰으로 들어와 함께 풉니다.\n      Left: 16\n      Top: 16\n      Width: 328\n      Height: 48\n  - name: btnTV\n    type: Button\n    properties:\n      Caption: TV로 진행\n      Left: 16\n      Top: 80\n      Width: 328\n      Height: 48\n  - name: btnPhone\n    type: Button\n    properties:\n      Caption: 폰으로 참여\n      Left: 16\n      Top: 144\n      Width: 328\n      Height: 48\n",
    "FormStart.gbas": "' 실시간 퀴즈 LiveQuiz (docs/LANGUAGE.md 11.12): 한 프로젝트를 TV와 폰이\n' 함께 씁니다. TV 쪽은 Room으로 방을 만들어 코드를 보여 주고 문제를 내며,\n' 폰 쪽은 그 코드로 들어와 답을 보냅니다. 빨리 맞힐수록 점수가 많고,\n' TV에는 점수만큼 캐릭터가 달려 나갑니다.\n'\n' 중계 서버: Room.Server가 비어 있으면 데스크톱 IDE가 이 컴퓨터에 중계\n' 서버를 켭니다. 폰에서 해 보려면 디버그 메뉴의 \"같은 네트워크의 기기 허용\"을\n' 켭니다. 앱으로 내보낼 때는 두 폼의 rmQuiz.Server에 자기 중계 서버 주소\n' (wss://relay.example.com/room 같은)를 넣습니다(docs/RELAY_SERVER.ko.md).\n\nSub btnTV_Click()\n    FormTV.Show()\n    Me.Hide()\nEnd Sub\n\nSub btnPhone_Click()\n    FormPhone.Show()\n    Me.Hide()\nEnd Sub\n",
    "FormTV.form.yaml": "formatVersion: 1\nproperties:\n  Caption: LiveQuiz - TV\n  Width: 640\n  Height: 480\ncontrols:\n  - name: lblCode\n    type: Label\n    properties:\n      Caption: 방을 만드는 중…\n      Left: 16\n      Top: 4\n      Width: 440\n      Height: 36\n      FontSize: 24.0\n      FontBold: true\n      ForeColor: Navy\n  - name: lblHelp\n    type: Label\n    properties:\n      Caption: 폰에서 LiveQuiz를 열고 \"폰으로 참여\"를 고른 뒤 이 코드를 넣으세요.\n      Left: 16\n      Top: 40\n      Width: 440\n  - name: btnNext\n    type: Button\n    properties:\n      Caption: 시작\n      Left: 16\n      Top: 68\n      Width: 120\n  - name: lblTime\n    type: Label\n    properties:\n      Left: 152\n      Top: 74\n      Width: 304\n  - name: lblQuestion\n    type: Label\n    properties:\n      Left: 16\n      Top: 112\n      Width: 440\n  - name: lblChoices\n    type: Label\n    properties:\n      Left: 16\n      Top: 140\n      Width: 440\n      Height: 40\n  - name: imgQuestion\n    type: Image\n    properties:\n      Left: 480\n      Top: 176\n      Width: 144\n      Height: 96\n  - name: lstPlayers\n    type: ListBox\n    properties:\n      Left: 480\n      Top: 12\n      Width: 144\n      Height: 156\n  - name: lblFinish\n    type: Label\n    properties:\n      Caption: 결승선 ▶\n      Left: 400\n      Top: 188\n      Width: 72\n  - name: rmQuiz\n    type: Room\n    properties:\n      Nickname: TV\n  - name: tmrQuestion\n    type: Timer\n    properties:\n      Interval: 1000\n",
    "FormTV.gbas": "' TV 쪽: 방을 만들고, 들어온 사람마다 캐릭터를 하나씩 세우고, 문제를 냅니다.\n' 폰과는 JSON 글로 이야기합니다:\n'   TV → 모두  {\"kind\":\"question\",\"no\":1,\"text\":\"…\",\"choices\":[…],\"seconds\":15,\"host\":\"m1\"}\n'   폰 → TV    {\"kind\":\"answer\",\"no\":1,\"choice\":2}\n'   TV → 그 폰 {\"kind\":\"result\",\"no\":1,\"correct\":true,\"score\":10}\n'   TV → 모두  {\"kind\":\"score\",\"board\":[{\"member\":\"m2\",\"nickname\":\"민지\",\"score\":10}, …]}\n'   TV → 모두  {\"kind\":\"end\"}\n\nStructure Question\n    Text As String\n    Choices(3) As String\n    Answer As Integer       ' 정답 보기의 번호(0부터)\n    Picture As String       ' 그림 문제의 그림 이름, 없으면 \"\"\nEnd Structure\n\nStructure Player\n    Member As String        ' 방에서의 ID(m2, m3, …)\n    Nickname As String\n    Score As Integer\n    Answered As Boolean     ' 이번 문제에 답했는지\nEnd Structure\n\nConst Seconds As Integer = 15   ' 문제 하나에 주는 시간\nConst Finish As Integer = 400   ' 결승선의 Left\n\nDim questions(6) As Question\nDim players As New List(Of Player)\nDim runners As New List(Of Image)   ' players와 같은 순서\nDim current As Integer = -1         ' 지금 문제의 번호(0부터), 시작 전에는 -1\nDim secondsLeft As Integer\nDim rightSoFar As Integer           ' 이번 문제를 맞힌 사람 수\nDim asking As Boolean               ' 문제를 내고 답을 기다리는 중인지\n\nSub Form_Load()\n    questions(0) = New Question With {.Text = \"대한민국의 수도는 어디일까요?\",\n                                      .Choices = {\"부산\", \"서울\", \"대구\", \"인천\"}, .Answer = 1}\n    questions(1) = New Question With {.Text = \"윤년이 아닌 해는 며칠일까요?\",\n                                      .Choices = {\"360일\", \"365일\", \"366일\", \"370일\"}, .Answer = 1}\n    questions(2) = New Question With {.Text = \"1기압에서 물이 끓는 온도는?\",\n                                      .Choices = {\"50도\", \"80도\", \"100도\", \"120도\"}, .Answer = 2}\n    questions(3) = New Question With {.Text = \"세종대왕이 만든 글자는?\",\n                                      .Choices = {\"한자\", \"한글\", \"가나\", \"알파벳\"}, .Answer = 1}\n    questions(4) = New Question With {.Text = \"7 × 8은 얼마일까요?\",\n                                      .Choices = {\"54\", \"56\", \"58\", \"64\"}, .Answer = 1}\n    questions(5) = New Question With {.Text = \"이 도형의 이름은?\",\n                                      .Choices = {\"사각형\", \"원\", \"삼각형\", \"오각형\"}, .Answer = 2,\n                                      .Picture = \"triangle.png\"}\n    questions(6) = New Question With {.Text = \"이 도형의 꼭짓점은 몇 개일까요?\",\n                                      .Choices = {\"4개\", \"5개\", \"6개\", \"8개\"}, .Answer = 1,\n                                      .Picture = \"pentagon.png\"}\n    ' 방이 만들어질 때까지 기다리므로, 다음 줄에서 코드를 읽을 수 있습니다.\n    rmQuiz.Create()\n    lblCode.Caption = \"방 코드: \" & rmQuiz.Code\nEnd Sub\n\n' 누가 들어오면: 목록에 넣고, 달릴 캐릭터를 하나 세웁니다.\nSub rmQuiz_Joined(e As RoomEventArgs)\n    players.Add(New Player With {.Member = e.Member, .Nickname = e.Nickname})\n    Dim lane As Integer = (players.Count - 1) Mod 5\n    Dim runner As New Image\n    runner.Picture = \"runner\" & ((players.Count - 1) Mod 4 + 1) & \".png\"\n    runner.Width = 48\n    runner.Height = 48\n    runner.Left = 16\n    runner.Top = 212 + lane * 52\n    Me.Controls.Add(runner)\n    runners.Add(runner)\n    ShowPlayers()\nEnd Sub\n\n' 누가 나가면: 목록과 캐릭터를 치웁니다.\nSub rmQuiz_Left(e As RoomEventArgs)\n    Dim i As Integer = IndexOfMember(e.Member)\n    If i < 0 Then Exit Sub\n    Me.Controls.Remove(runners(i))\n    runners.RemoveAt(i)\n    players.RemoveAt(i)\n    ShowPlayers()\nEnd Sub\n\nSub btnNext_Click()\n    If current = -1 Then\n        ' 시작하면 더는 들어오지 못하게 방을 잠급니다.\n        rmQuiz.Lock()\n    End If\n    current = current + 1\n    rightSoFar = 0\n    For i As Integer = 0 To players.Count - 1\n        Dim p As Player = players(i)\n        p.Answered = False\n        players(i) = p\n    Next\n    Dim q As Question = questions(current)\n    lblQuestion.Caption = (current + 1) & \". \" & q.Text\n    lblChoices.Caption = \"1) \" & q.Choices(0) & \"   2) \" & q.Choices(1) & _\n                         \"   3) \" & q.Choices(2) & \"   4) \" & q.Choices(3)\n    imgQuestion.Picture = q.Picture\n    ' 문제를 모두에게 보냅니다. 폰은 \"host\"로 답을 보낼 곳을 압니다.\n    Dim message As New Json\n    message(\"kind\") = \"question\"\n    message(\"no\") = current + 1\n    message(\"text\") = q.Text\n    Dim choices As Json = Json.Array()\n    For Each c In q.Choices\n        choices.Add(c)\n    Next\n    message(\"choices\") = choices\n    message(\"seconds\") = Seconds\n    message(\"host\") = rmQuiz.Me\n    rmQuiz.Send(message.Text)\n    secondsLeft = Seconds\n    lblTime.Caption = \"남은 시간: \" & secondsLeft & \"초\"\n    asking = True\n    ' 답을 받는 동안에는 누를 수 없게 합니다.\n    btnNext.Enabled = False\n    tmrQuestion.Start()\nEnd Sub\n\nSub tmrQuestion_Tick()\n    secondsLeft = secondsLeft - 1\n    lblTime.Caption = \"남은 시간: \" & secondsLeft & \"초\"\n    If secondsLeft <= 0 Then EndQuestion()\nEnd Sub\n\n' 답이 오면: 맞았으면 빨리 맞힌 순서대로 10, 8, 6, 4, 그 뒤로는 3점.\nSub rmQuiz_Message(e As RoomEventArgs)\n    Dim m As Json = e.Json\n    If m(\"kind\").AsString <> \"answer\" Then Exit Sub\n    If Not asking Or m(\"no\").AsInteger <> current + 1 Then Exit Sub\n    Dim i As Integer = IndexOfMember(e.Member)\n    If i < 0 Then Exit Sub\n    Dim p As Player = players(i)\n    If p.Answered Then Exit Sub\n    p.Answered = True\n    Dim result As New Json\n    result(\"kind\") = \"result\"\n    result(\"no\") = current + 1\n    If m(\"choice\").AsInteger = questions(current).Answer Then\n        rightSoFar = rightSoFar + 1\n        Dim points As Integer = 12 - 2 * rightSoFar\n        If points < 3 Then points = 3\n        p.Score = p.Score + points\n        result(\"correct\") = True\n    Else\n        result(\"correct\") = False\n    End If\n    result(\"score\") = p.Score\n    players(i) = p\n    rmQuiz.SendTo(e.Member, result.Text)\n    ShowPlayers()\n    If EveryoneAnswered() Then EndQuestion()\nEnd Sub\n\nSub EndQuestion()\n    tmrQuestion.Stop()\n    asking = False\n    Dim q As Question = questions(current)\n    lblTime.Caption = \"정답: \" & (q.Answer + 1) & \") \" & q.Choices(q.Answer)\n    ' 순위표를 모두에게 보냅니다.\n    Dim board As Json = Json.Array()\n    For Each p In Ranked()\n        Dim row As New Json\n        row(\"member\") = p.Member\n        row(\"nickname\") = p.Nickname\n        row(\"score\") = p.Score\n        board.Add(row)\n    Next\n    Dim message As New Json\n    message(\"kind\") = \"score\"\n    message(\"board\") = board\n    rmQuiz.Send(message.Text)\n    If current = UBound(questions) Then\n        rmQuiz.Send(\"{\"\"kind\"\":\"\"end\"\"}\")\n        lblQuestion.Caption = \"끝! 1등: \" & Winner()\n        btnNext.Caption = \"끝\"\n    Else\n        btnNext.Caption = \"다음 문제\"\n        btnNext.Enabled = True\n    End If\nEnd Sub\n\nSub rmQuiz_Closed(e As RoomEventArgs)\n    tmrQuestion.Stop()\n    asking = False\n    lblCode.Caption = \"방이 끝났습니다(\" & e.Reason & \").\"\n    btnNext.Enabled = False\nEnd Sub\n\n' 목록에는 별명과 점수를, 캐릭터는 점수만큼 결승선 쪽으로.\nSub ShowPlayers()\n    lstPlayers.Clear()\n    Dim most As Integer = (UBound(questions) + 1) * 10\n    For i As Integer = 0 To players.Count - 1\n        Dim p As Player = players(i)\n        lstPlayers.AddItem(p.Nickname & \" \" & p.Score & \"점\")\n        runners(i).Left = 16 + (Finish - 16) * p.Score \\ most\n    Next\nEnd Sub\n\nFunction IndexOfMember(member As String) As Integer\n    For i As Integer = 0 To players.Count - 1\n        If players(i).Member = member Then Return i\n    Next\n    Return -1\nEnd Function\n\nFunction EveryoneAnswered() As Boolean\n    For Each p In players\n        If Not p.Answered Then Return False\n    Next\n    Return players.Count > 0\nEnd Function\n\n' 점수가 높은 순서로 늘어놓은 목록(같으면 먼저 들어온 사람이 앞).\nFunction Ranked() As List(Of Player)\n    Dim result As New List(Of Player)\n    For Each p In players\n        Dim at As Integer = result.Count\n        For i As Integer = 0 To result.Count - 1\n            If p.Score > result(i).Score Then\n                at = i\n                Exit For\n            End If\n        Next\n        result.Insert(at, p)\n    Next\n    Return result\nEnd Function\n\nFunction Winner() As String\n    Dim ranked As List(Of Player) = Ranked()\n    If ranked.Count = 0 Then Return \"없음\"\n    Return ranked(0).Nickname & \" (\" & ranked(0).Score & \"점)\"\nEnd Function\n",
    "LiveQuiz.gbproj": "formatVersion: 2\nname: LiveQuiz\nstartup: FormStart\nforms:\n  - FormStart\n  - FormTV\n  - FormPhone\npictures:\n  - triangle.png\n  - pentagon.png\n  - runner1.png\n  - runner2.png\n  - runner3.png\n  - runner4.png\n",
  },
  "notes": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 메모장\n  Width: 420\n  Height: 320\ncontrols:\n  - name: txtNote\n    type: TextBox\n    properties:\n      Left: 16\n      Top: 16\n      Width: 284\n      Anchor: Left Top Right\n  - name: btnAdd\n    type: Button\n    properties:\n      Caption: 추가\n      Left: 308\n      Top: 16\n      Width: 96\n      Anchor: Top Right\n  - name: lstNotes\n    type: ListBox\n    properties:\n      Left: 16\n      Top: 56\n      Width: 388\n      Height: 180\n      Anchor: Left Top Right Bottom\n  - name: btnDelete\n    type: Button\n    properties:\n      Caption: 지우기\n      Left: 308\n      Top: 248\n      Width: 96\n      Anchor: Right Bottom\n  - name: lblCount\n    type: Label\n    properties:\n      Left: 16\n      Top: 254\n      Width: 284\n      Anchor: Left Right Bottom\n",
    "Form1.gbas": "' Notes kept in the app's own database (docs/DESIGN.md D126): every app\n' has an SQLite file of its own, data.db, that Database opens when first\n' used. Each note goes in with Database.Execute, the list is filled from\n' Database.Query, and a value always goes in for a ?, never joined into\n' the SQL, so that a quote in a note cannot break the statement. The notes\n' are still there the next time the program runs.\nDim notes As Table\n\nSub Form_Load()\n    Database.Execute(\"CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY, text TEXT NOT NULL, written TEXT NOT NULL)\")\n    ShowNotes()\nEnd Sub\n\nSub btnAdd_Click()\n    Dim text As String = txtNote.Text.Trim()\n    If text = \"\" Then Exit Sub\n    Database.Execute(\"INSERT INTO notes (text, written) VALUES (?, ?)\", text, Now)\n    txtNote.Text = \"\"\n    ShowNotes()\nEnd Sub\n\nSub btnDelete_Click()\n    If lstNotes.ListIndex < 0 Then Exit Sub\n    Database.Execute(\"DELETE FROM notes WHERE id = ?\", notes.Cell(lstNotes.ListIndex, \"id\"))\n    ShowNotes()\nEnd Sub\n\n' The notes, newest first, and how many there are.\nSub ShowNotes()\n    notes = Database.Query(\"SELECT id, text, written FROM notes ORDER BY id DESC\")\n    lstNotes.Clear()\n    For r = 0 To notes.RowCount - 1\n        lstNotes.AddItem(Left(notes.Cell(r, \"written\"), 16) & \"  \" & notes.Cell(r, \"text\"))\n    Next\n    lblCount.Caption = Database.Scalar(\"SELECT COUNT(*) FROM notes\") & \"개의 메모\"\nEnd Sub\n",
    "Notes.gbproj":
        "formatVersion: 1\nname: Notes\nstartup: Form1\nforms:\n  - Form1\n",
  },
  "quiz": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 퀴즈\n  Width: 400\n  Height: 300\ncontrols:\n  - name: lblNumber\n    type: Label\n    properties:\n      Left: 16\n      Top: 12\n      Width: 368\n  - name: lblQuestion\n    type: Label\n    properties:\n      Left: 16\n      Top: 40\n      Width: 368\n  - name: lstChoices\n    type: ListBox\n    properties:\n      Left: 16\n      Top: 72\n      Width: 232\n      Height: 116\n  - name: imgQuestion\n    type: Image\n    properties:\n      Left: 264\n      Top: 72\n      Width: 120\n      Height: 116\n  - name: chkShowAnswer\n    type: CheckBox\n    properties:\n      Caption: 틀리면 정답 보여 주기\n      Left: 16\n      Top: 200\n      Width: 240\n  - name: btnCheck\n    type: Button\n    properties:\n      Caption: 정답 확인\n      Left: 16\n      Top: 248\n      Width: 136\n  - name: lblScore\n    type: Label\n    properties:\n      Left: 168\n      Top: 252\n      Width: 216\n",
    "Form1.gbas": "' 작은 퀴즈: 문제를 보여 주고, ListBox의 보기 가운데 하나를 고르면\n' 맞았는지 알려 주며 점수를 셉니다. 최고 점수는 저장해 두었다가 다음에\n' 실행할 때도 보여 줍니다. 그림 문제는 프로젝트의 그림(pictures 폴더)을\n' Image에 보여 줍니다.\n\n' 문제 하나에 딸린 것을 한 이름으로 묶습니다(Structure).\nStructure Question\n    Text As String\n    Choices(3) As String    ' 보기 네 개\n    Answer As Integer       ' 정답 보기의 번호(0부터)\n    Picture As String       ' 문제의 그림 이름. 그림이 없는 문제는 \"\"\nEnd Structure\n\nDim questions(6) As Question\nDim current As Integer\nDim score As Integer\nDim best As Integer\n\nSub Form_Load()\n    ' New … With { }로 문제 하나를 한 번에 만듭니다. 보기는 { }로 적은 배열입니다.\n    questions(0) = New Question With {.Text = \"대한민국의 수도는 어디일까요?\",\n                                      .Choices = {\"부산\", \"서울\", \"대구\", \"인천\"}, .Answer = 1}\n    questions(1) = New Question With {.Text = \"윤년이 아닌 해는 며칠일까요?\",\n                                      .Choices = {\"360일\", \"365일\", \"366일\", \"370일\"}, .Answer = 1}\n    questions(2) = New Question With {.Text = \"1기압에서 물이 끓는 온도는?\",\n                                      .Choices = {\"50도\", \"80도\", \"100도\", \"120도\"}, .Answer = 2}\n    questions(3) = New Question With {.Text = \"세종대왕이 만든 글자는?\",\n                                      .Choices = {\"한자\", \"한글\", \"가나\", \"알파벳\"}, .Answer = 1}\n    questions(4) = New Question With {.Text = \"7 × 8은 얼마일까요?\",\n                                      .Choices = {\"54\", \"56\", \"58\", \"64\"}, .Answer = 1}\n    questions(5) = New Question With {.Text = \"이 도형의 이름은?\",\n                                      .Choices = {\"사각형\", \"원\", \"삼각형\", \"오각형\"}, .Answer = 2,\n                                      .Picture = \"triangle.png\"}\n    questions(6) = New Question With {.Text = \"이 도형의 꼭짓점은 몇 개일까요?\",\n                                      .Choices = {\"4개\", \"5개\", \"6개\", \"8개\"}, .Answer = 1,\n                                      .Picture = \"pentagon.png\"}\n    ' 지난 실행까지의 최고 점수. 저장된 것이 없으면 \"0\"입니다.\n    best = CInt(GetSetting(\"best\", \"0\"))\n    ShowQuestion(0)\nEnd Sub\n\nSub ShowQuestion(number As Integer)\n    current = number\n    Dim q As Question = questions(number)\n    lblNumber.Caption = \"문제 \" & (number + 1) & \" / \" & (UBound(questions) + 1)\n    lblQuestion.Caption = q.Text\n    ' 그림 이름을 넣으면 그 그림을, \"\"을 넣으면 아무것도 보여 주지 않습니다.\n    imgQuestion.Picture = q.Picture\n    ' Clear()는 고른 항목도 지웁니다. 그래서 고른 것이 있었다면\n    ' lstChoices_Changed가 실행되고, ListIndex는 -1(고른 것 없음)이 됩니다.\n    lstChoices.Clear()\n    For Each choice In q.Choices\n        lstChoices.AddItem(choice)\n    Next\n    lblScore.Caption = \"점수: \" & score & \" · 최고 점수: \" & best\nEnd Sub\n\nSub lstChoices_Changed()\n    ' ListIndex가 바뀔 때마다 실행됩니다: 보기를 고를 때, 그리고 Clear()로\n    ' 고른 것이 없어질 때(ListIndex = -1).\n    If lstChoices.ListIndex = -1 Then\n        btnCheck.Caption = \"정답 확인\"\n    Else\n        btnCheck.Caption = \"확인: \" & lstChoices.Text\n    End If\nEnd Sub\n\nSub btnCheck_Click()\n    If lstChoices.ListIndex = -1 Then\n        MsgBox(\"먼저 보기를 하나 고르세요.\")\n        Exit Sub\n    End If\n    If lstChoices.ListIndex = questions(current).Answer Then\n        score = score + 1\n        MsgBox(\"정답입니다!\")\n    ElseIf chkShowAnswer.Checked Then\n        MsgBox(\"틀렸습니다. 정답: \" & lstChoices.List(questions(current).Answer))\n    Else\n        MsgBox(\"틀렸습니다.\")\n    End If\n    If current < UBound(questions) Then\n        ShowQuestion(current + 1)\n    Else\n        Dim message As String = (UBound(questions) + 1) & \"문제 가운데 \" & score & \"문제를 맞혔습니다.\"\n        If score > best Then\n            ' SaveSetting으로 저장한 값은 프로그램을 다시 실행해도 남습니다.\n            best = score\n            SaveSetting(\"best\", best)\n            message = message & \" 새 최고 점수입니다!\"\n        End If\n        MsgBox(message & \" 처음부터 다시 합니다.\")\n        score = 0\n        ShowQuestion(0)\n    End If\nEnd Sub\n",
    "Quiz.gbproj": "formatVersion: 2\nname: Quiz\nstartup: Form1\nforms:\n  - Form1\npictures:\n  - triangle.png\n  - pentagon.png\n",
  },
  "scores": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 성적표\n  Width: 480\n  Height: 340\ncontrols:\n  - name: grdScores\n    type: Grid\n    properties:\n      Left: 16\n      Top: 16\n      Width: 448\n      Height: 220\n      Anchor: Left Top Right Bottom\n  - name: lblTotal\n    type: Label\n    properties:\n      Left: 16\n      Top: 248\n      Width: 448\n      Anchor: Left Right Bottom\n  - name: btnOpen\n    type: Button\n    properties:\n      Caption: CSV 열기\n      Left: 16\n      Top: 288\n      Width: 120\n      Anchor: Left Bottom\n  - name: btnPdf\n    type: Button\n    properties:\n      Caption: PDF로 저장\n      Left: 144\n      Top: 288\n      Width: 120\n      Anchor: Left Bottom\n  - name: lblStatus\n    type: Label\n    properties:\n      Left: 280\n      Top: 294\n      Width: 184\n      Anchor: Left Right Bottom\n  - name: dlgOpen\n    type: OpenFileDialog\n    properties:\n      Title: 명단 열기\n      Filter: CSV 파일|*.csv\n  - name: dlgSave\n    type: SaveFileDialog\n    properties:\n      Title: 성적 저장\n      Filter: PDF 파일|*.pdf\n      FileName: 성적.pdf\n",
    "Form1.gbas": "' Work automation (docs/DESIGN.md D117): a list in a Grid, its total and\n' average, saved as a PDF file. It starts with three names; CSV 열기\n' (Open CSV) reads your own list, a CSV file with a column named 점수\n' (score), such as one Excel saves. Change a score in the Grid and the\n' total follows. A list of more than four columns is saved on pages\n' turned on their side.\nSub Form_Load()\n    grdScores.AddColumn(\"이름\")\n    grdScores.AddColumn(\"반\")\n    grdScores.AddColumn(\"점수\")\n    AddStudent(\"김하나\", \"1반\", 90)\n    AddStudent(\"박둘\", \"2반\", 85)\n    AddStudent(\"이셋\", \"1반\", 70)\n    ShowTotal()\nEnd Sub\n\nSub AddStudent(name As String, group As String, score As Integer)\n    Dim r As Integer = grdScores.AddRow()\n    grdScores.Cell(r, \"이름\") = name\n    grdScores.Cell(r, \"반\") = group\n    grdScores.Cell(r, \"점수\") = score\nEnd Sub\n\nSub ShowTotal()\n    If grdScores.Column(\"점수\") < 0 Then\n        lblTotal.Caption = \"점수 열이 없는 명단입니다.\"\n    ElseIf grdScores.RowCount = 0 Then\n        lblTotal.Caption = \"명단이 비어 있습니다.\"\n    Else\n        Dim total As Double = 0\n        For i As Integer = 0 To grdScores.RowCount - 1\n            total = total + Val(grdScores.Cell(i, \"점수\"))\n        Next\n        Dim average As String = Format(total / grdScores.RowCount, \"0.0\")\n        lblTotal.Caption = grdScores.RowCount & \"명, 합계 \" & total & \", 평균 \" & average\n    End If\nEnd Sub\n\nSub grdScores_Changed()\n    ShowTotal()\nEnd Sub\n\nSub btnOpen_Click()\n    If dlgOpen.ShowDialog() = DialogResult.OK Then\n        grdScores.LoadCsv(dlgOpen.FileName)\n        ShowTotal()\n    End If\nEnd Sub\n\nSub btnPdf_Click()\n    If dlgSave.ShowDialog() = DialogResult.OK Then\n        Dim pdf As New PdfDocument\n        pdf.TitleSize = 20\n        If grdScores.ColumnCount > 4 Then\n            pdf.Landscape = True\n        End If\n        pdf.AddTitle(\"성적표\")\n        pdf.AddText(lblTotal.Caption)\n        pdf.AddTable(grdScores)\n        pdf.Save(dlgSave.FileName)\n        lblStatus.Caption = \"저장했습니다: \" & dlgSave.FileName\n    End If\nEnd Sub\n",
    "Scores.gbproj":
        "formatVersion: 1\nname: Scores\nstartup: Form1\nforms:\n  - Form1\n",
  },
  "shooter": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: Shooter\n  Width: 480\n  Height: 640\n  BackColor: \"#0B1026\"\ncontrols:\n  - name: lblScore\n    type: Label\n    properties:\n      Caption: 점수 0\n      Left: 12\n      Top: 8\n      Width: 160\n      Height: 24\n      FontSize: 14.0\n      FontBold: true\n      ForeColor: White\n  - name: lblLives\n    type: Label\n    properties:\n      Caption: 목숨 3\n      Left: 308\n      Top: 8\n      Width: 160\n      Height: 24\n      FontSize: 14.0\n      FontBold: true\n      ForeColor: White\n      Anchor: Right Top\n  - name: lblMessage\n    type: Label\n    properties:\n      Caption: 시작을 누르세요\n      Left: 40\n      Top: 260\n      Width: 400\n      Height: 40\n      FontSize: 22.0\n      FontBold: true\n      ForeColor: Gold\n  - name: btnStart\n    type: Button\n    properties:\n      Caption: 시작\n      Left: 180\n      Top: 592\n      Width: 120\n      Height: 36\n      Anchor: Left Bottom\n  - name: sprShip\n    type: Sprite\n    properties:\n      Frames: ship.png\n      Shape: Rectangle\n      Left: 224\n      Top: 540\n      Width: 32\n      Height: 32\n  - name: tmrGame\n    type: Timer\n    properties:\n      Interval: 16\n",
    "Form1.gbas": "' 슈팅 게임의 정석(docs/DESIGN.md D138): Timer 하나가 게임 루프이고,\n' 물체마다 상태(Sprite와 배열)가 있으며, 적은 시간표대로 나옵니다.\n' ← →로 움직이고 스페이스로 쏩니다. 키보드가 있는 데스크톱과 웹용입니다.\n\n' 적이 나오는 시간표의 한 줄: 몇 ms에, 몇 번째 길에, 어떤 적이.\nStructure Wave\n    At As Integer           ' 시작한 뒤 흐른 ms\n    Lane As Integer         ' 0부터 4까지, 왼쪽부터\n    Kind As Integer         ' 0: 느린 적, 1: 빠른 적\nEnd Structure\n\nConst Lanes As Integer = 5\nConst ShipSpeed As Double = 240     ' 초당 픽셀\nConst ShotSpeed As Double = -420\nConst FireGap As Integer = 220      ' 발사 사이의 ms\n\nDim shots(7) As Sprite\nDim enemies(19) As Sprite\nDim boomUntil(19) As Integer        ' 터지는 적이 사라질 때(ms); 0이면 터지는 중이 아님\nDim waves(23) As Wave\nDim nextWave As Integer\nDim startedAt As Integer\nDim lastTime As Integer\nDim lastShot As Integer\nDim score As Integer\nDim lives As Integer\n\nSub Form_Load()\n    Dim i As Integer\n    ' 탄과 적은 미리 만들어 두고, 쓸 때만 보입니다(Visible).\n    For i = 0 To UBound(shots)\n        shots(i) = New Sprite With {.Frames = \"shot.png\", .Width = 6, .Height = 14,\n                                    .Shape = \"Rectangle\", .SpeedY = ShotSpeed, .Visible = False}\n        Me.Controls.Add(shots(i))\n    Next\n    For i = 0 To UBound(enemies)\n        enemies(i) = New Sprite With {.Frames = \"enemy1.png, enemy2.png\", .FrameTime = 150,\n                                      .Width = 32, .Height = 32, .Shape = \"Circle\", .Visible = False}\n        Me.Controls.Add(enemies(i))\n    Next\n    ' 시간표: 처음에는 느린 적이 하나씩, 나중에는 빠른 적이 둘씩.\n    For i = 0 To 11\n        waves(i) = New Wave With {.At = 1000 + i * 1500, .Lane = (i * 3) Mod Lanes, .Kind = 0}\n    Next\n    For i = 12 To 23\n        waves(i) = New Wave With {.At = 19000 + (i - 12) * 900, .Lane = (i * 2 + 1) Mod Lanes, .Kind = 1}\n    Next\n    lblMessage.Caption = \"시작을 누르세요\"\nEnd Sub\n\nSub btnStart_Click()\n    Dim i As Integer\n    For i = 0 To UBound(shots)\n        shots(i).Visible = False\n    Next\n    For i = 0 To UBound(enemies)\n        enemies(i).Visible = False\n        boomUntil(i) = 0\n    Next\n    score = 0\n    lives = 3\n    nextWave = 0\n    sprShip.X = (Me.Width - sprShip.Width) / 2\n    sprShip.Visible = True\n    ShowStatus()\n    lblMessage.Caption = \"\"\n    btnStart.Enabled = False\n    ' 웹에서는 클릭 뒤에야 소리가 납니다: 시작 버튼이 그 클릭입니다.\n    Sound.PlayMusic(\"music.wav\")\n    startedAt = Milliseconds()\n    lastTime = startedAt\n    lastShot = 0\n    tmrGame.Start()\nEnd Sub\n\n' 게임 루프: 흐른 시간을 재고, 키를 읽고, 모두 움직이고, 부딪힘을 봅니다.\nSub tmrGame_Tick()\n    Dim now As Integer = Milliseconds()\n    Dim dt As Integer = now - lastTime\n    lastTime = now\n    Dim i As Integer\n    Dim j As Integer\n\n    ' 1. 우주선: 누른 키대로 속도를 정하고 움직입니다. 화면 밖으로는 못 갑니다.\n    sprShip.SpeedX = 0\n    If Keyboard.IsDown(Keys.Left) Then sprShip.SpeedX = -ShipSpeed\n    If Keyboard.IsDown(Keys.Right) Then sprShip.SpeedX = ShipSpeed\n    sprShip.Move(dt)\n    If sprShip.X < 0 Then sprShip.X = 0\n    If sprShip.X > Me.Width - sprShip.Width Then sprShip.X = Me.Width - sprShip.Width\n\n    ' 2. 발사: 스페이스를 누르고 있으면 FireGap마다 쉬는 탄 하나를 씁니다.\n    If Keyboard.IsDown(Keys.Space) And now - lastShot >= FireGap Then\n        For i = 0 To UBound(shots)\n            If Not shots(i).Visible Then\n                shots(i).X = sprShip.X + (sprShip.Width - shots(i).Width) / 2\n                shots(i).Y = sprShip.Y - shots(i).Height\n                shots(i).Visible = True\n                lastShot = now\n                Sound.Play(\"shot.wav\")\n                Exit For\n            End If\n        Next\n    End If\n\n    ' 3. 시간표: 때가 된 적을 내보냅니다.\n    Do While nextWave <= UBound(waves)\n        If now - startedAt < waves(nextWave).At Then Exit Do\n        Spawn(waves(nextWave))\n        nextWave = nextWave + 1\n    Loop\n\n    ' 4. 탄과 적을 움직입니다. 화면을 벗어난 탄은 쉬고, 벗어난 적은 목숨을 하나 뺏습니다.\n    For i = 0 To UBound(shots)\n        If shots(i).Visible Then\n            shots(i).Move(dt)\n            If shots(i).Y + shots(i).Height < 0 Then shots(i).Visible = False\n        End If\n    Next\n    For i = 0 To UBound(enemies)\n        If enemies(i).Visible Then\n            enemies(i).Move(dt)\n            If boomUntil(i) > 0 Then\n                If now >= boomUntil(i) Then\n                    enemies(i).Visible = False\n                    boomUntil(i) = 0\n                End If\n            ElseIf enemies(i).Y > Me.Height Then\n                enemies(i).Visible = False\n                LoseLife()\n            End If\n        End If\n    Next\n\n    ' 5. 부딪힘: 탄마다 적마다 Hits 한 번씩. 맞은 적은 터지는 그림으로 바뀝니다.\n    For i = 0 To UBound(shots)\n        If shots(i).Visible Then\n            For j = 0 To UBound(enemies)\n                If enemies(j).Visible And boomUntil(j) = 0 Then\n                    If shots(i).Hits(enemies(j)) Then\n                        shots(i).Visible = False\n                        Explode(j, now)\n                        score = score + 10\n                        ShowStatus()\n                        Exit For\n                    End If\n                End If\n            Next\n        End If\n    Next\n    For j = 0 To UBound(enemies)\n        If enemies(j).Visible And boomUntil(j) = 0 Then\n            If sprShip.Hits(enemies(j)) Then\n                Explode(j, now)\n                LoseLife()\n            End If\n        End If\n    Next\nEnd Sub\n\n' 시간표의 한 줄대로 쉬는 적 하나를 길 위에 내보냅니다.\nSub Spawn(wave As Wave)\n    Dim i As Integer\n    For i = 0 To UBound(enemies)\n        If Not enemies(i).Visible Then\n            Dim laneWidth As Double = Me.Width / Lanes\n            enemies(i).Frames = \"enemy1.png, enemy2.png\"\n            enemies(i).FrameTime = 150\n            enemies(i).X = wave.Lane * laneWidth + (laneWidth - enemies(i).Width) / 2\n            enemies(i).Y = -enemies(i).Height\n            enemies(i).SpeedY = 90 + wave.Kind * 70\n            enemies(i).Visible = True\n            boomUntil(i) = 0\n            Exit For\n        End If\n    Next\nEnd Sub\n\n' 적이 터집니다: 그림이 폭발로 바뀌고, 멈춘 채 잠시 뒤 사라집니다.\nSub Explode(index As Integer, now As Integer)\n    enemies(index).Frames = \"boom1.png, boom2.png, boom3.png\"\n    enemies(index).FrameTime = 80\n    enemies(index).SpeedY = 0\n    boomUntil(index) = now + 240\n    Sound.Play(\"hit.wav\")\nEnd Sub\n\nSub LoseLife()\n    lives = lives - 1\n    ShowStatus()\n    If lives <= 0 Then GameOver()\nEnd Sub\n\nSub GameOver()\n    tmrGame.Stop()\n    Sound.StopMusic()\n    sprShip.Visible = False\n    lblMessage.Caption = \"게임 끝: \" & score & \"점\"\n    btnStart.Caption = \"다시\"\n    btnStart.Enabled = True\nEnd Sub\n\nSub ShowStatus()\n    lblScore.Caption = \"점수 \" & score\n    lblLives.Caption = \"목숨 \" & lives\nEnd Sub\n",
    "Shooter.gbproj": "formatVersion: 4\nname: Shooter\nstartup: Form1\nforms:\n  - Form1\npictures:\n  - ship.png\n  - shot.png\n  - enemy1.png\n  - enemy2.png\n  - boom1.png\n  - boom2.png\n  - boom3.png\nsounds:\n  - shot.wav\n  - hit.wav\n  - music.wav\n",
  },
  "typing": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: Typing\n  Width: 320\n  Height: 160\ncontrols:\n  - name: txtName\n    type: TextBox\n    properties:\n      Left: 16\n      Top: 16\n      Width: 288\n  - name: lblMessage\n    type: Label\n    properties:\n      Left: 16\n      Top: 60\n      Width: 288\n  - name: btnHello\n    type: Button\n    properties:\n      Caption: Say hello\n      Left: 16\n      Top: 100\n      Width: 120\n",
    "Form1.gbas": "' Typing in a TextBox: Changed runs each time the input method commits\n' a character (docs/LANGUAGE.md §11.1). Try it with a Korean input method.\nDim clickCount As Integer\n\nSub Form_Load()\n    lblMessage.Caption = \"Type your name, or press the button\"\nEnd Sub\n\nSub txtName_Changed()\n    lblMessage.Caption = \"Hello, \" & txtName.Text\nEnd Sub\n\nSub btnHello_Click()\n    clickCount = clickCount + 1\n    Dim name = txtName.Text\n    If name = \"\" Then\n        name = InputBox(\"What is your name?\")\n    End If\n    MsgBox(\"Hello, \" & name & \"! (\" & clickCount & \")\")\nEnd Sub\n",
    "Typing.gbproj":
        "formatVersion: 1\nname: Typing\nstartup: Form1\nforms:\n  - Form1\n",
  },
  "weather": {
    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 지금 날씨\n  Width: 360\n  Height: 220\ncontrols:\n  - name: lblCity\n    type: Label\n    properties:\n      Caption: 도시\n      Left: 16\n      Top: 20\n      Width: 48\n  - name: cboCity\n    type: ComboBox\n    properties:\n      Left: 64\n      Top: 16\n      Width: 160\n  - name: btnWeather\n    type: Button\n    properties:\n      Caption: 날씨 보기\n      Left: 240\n      Top: 16\n      Width: 104\n  - name: lblTemp\n    type: Label\n    properties:\n      Left: 16\n      Top: 64\n      Width: 328\n      Height: 32\n  - name: lblSky\n    type: Label\n    properties:\n      Left: 16\n      Top: 104\n      Width: 328\n  - name: lblWind\n    type: Label\n    properties:\n      Left: 16\n      Top: 136\n      Width: 328\n  - name: lblStatus\n    type: Label\n    properties:\n      Left: 16\n      Top: 176\n      Width: 328\n      Anchor: Left Top Right\n",
    "Form1.gbas": "' The weather now (docs/DESIGN.md D125): Http.GetJson asks Open-Meteo, a\n' free weather service that needs no key (https://open-meteo.com/), and\n' the answer's JSON is read member by member. The program waits where it\n' asks; the pointer shows waiting meanwhile. An answer that does not\n' come, or is not what was expected, is caught and shown.\nSub Form_Load()\n    cboCity.AddItem(\"서울\")\n    cboCity.AddItem(\"부산\")\n    cboCity.AddItem(\"제주\")\n    cboCity.ListIndex = 0\n    lblStatus.Caption = \"도시를 고르고 날씨 보기를 누르세요.\"\nEnd Sub\n\nSub btnWeather_Click()\n    Dim latitude As String = \"37.57\"\n    Dim longitude As String = \"126.98\"\n    Select Case cboCity.Text\n        Case \"부산\"\n            latitude = \"35.18\"\n            longitude = \"129.08\"\n        Case \"제주\"\n            latitude = \"33.50\"\n            longitude = \"126.53\"\n    End Select\n    Dim url As String = \"https://api.open-meteo.com/v1/forecast?latitude=\" & latitude & \"&longitude=\" & longitude & \"&current=temperature_2m,wind_speed_10m,weather_code&timezone=Asia%2FSeoul\"\n    lblStatus.Caption = \"가져오는 중…\"\n    Try\n        Dim reply As Json = Http.GetJson(url)\n        Dim now As Json = reply(\"current\")\n        Dim units As Json = reply(\"current_units\")\n        lblTemp.Caption = cboCity.Text & \" \" & now(\"temperature_2m\").AsDouble & units(\"temperature_2m\").AsString\n        lblSky.Caption = SkyOf(now(\"weather_code\").AsInteger)\n        lblWind.Caption = \"바람 \" & now(\"wind_speed_10m\").AsDouble & \" \" & units(\"wind_speed_10m\").AsString\n        lblStatus.Caption = now(\"time\").AsString & \" 기준\"\n    Catch ex As Exception\n        lblStatus.Caption = ex.Message\n    End Try\nEnd Sub\n\n' The sky from a WMO weather code, as Open-Meteo gives it.\nFunction SkyOf(code As Integer) As String\n    Select Case code\n        Case 0\n            Return \"맑음\"\n        Case 1, 2, 3\n            Return \"구름 조금에서 흐림\"\n        Case 45, 48\n            Return \"안개\"\n        Case 51 To 67\n            Return \"비\"\n        Case 71 To 77\n            Return \"눈\"\n        Case 80 To 82\n            Return \"소나기\"\n        Case 95 To 99\n            Return \"뇌우\"\n    End Select\n    Return \"날씨 코드 \" & code\nEnd Function\n",
    "Weather.gbproj":
        "formatVersion: 1\nname: Weather\nstartup: Form1\nforms:\n  - Form1\n",
  },
};

